/* 解析整数（十进制） */
static int64_t xlParseIntDec(const char* text)
{
	int64_t result = 0;
	while ( *text ) {
		if ( *text != '_' ) {
			result = result * 10 + (*text - '0');
		}
		text++;
	}
	return result;
}

/* 解析整数（十六进制） */
static int64_t xlParseIntHex(const char* text)
{
	int64_t result = 0;
	/* 跳过 0x 或 &H */
	if ( (text[0] == '0') && ((text[1] == 'x') || (text[1] == 'X')) ) {
		text += 2;
	} else if ( (text[0] == '&') && ((text[1] == 'h') || (text[1] == 'H')) ) {
		text += 2;
	}
	while ( *text ) {
		if ( *text != '_' ) {
			char c = *text;
			int digit;
			if ( (c >= '0') && (c <= '9') ) {
				digit = c - '0';
			} else if ( (c >= 'a') && (c <= 'f') ) {
				digit = c - 'a' + 10;
			} else if ( (c >= 'A') && (c <= 'F') ) {
				digit = c - 'A' + 10;
			} else {
				break;
			}
			result = result * 16 + digit;
		}
		text++;
	}
	return result;
}

/* 解析整数（八进制） */
static int64_t xlParseIntOct(const char* text)
{
	int64_t result = 0;
	/* 跳过 &O */
	text += 2;
	while ( *text ) {
		if ( *text != '_' ) {
			result = result * 8 + (*text - '0');
		}
		text++;
	}
	return result;
}

/* 解析整数（二进制） */
static int64_t xlParseIntBin(const char* text)
{
	int64_t result = 0;
	/* 跳过 0b 或 &B */
	if ( (text[0] == '0') && ((text[1] == 'b') || (text[1] == 'B')) ) {
		text += 2;
	} else if ( (text[0] == '&') && ((text[1] == 'b') || (text[1] == 'B')) ) {
		text += 2;
	}
	while ( *text ) {
		if ( *text != '_' ) {
			result = result * 2 + (*text - '0');
		}
		text++;
	}
	return result;
}

